// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Status_Reporting_Thread_control_process_status_reporting_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting)
  }

  /** helper function to set the values of all input ports.
   * @param status_in payload for data port status_in
   */
  def put_concrete_inputs(status_in : FAA_Autopilot_Engagement.AP_Status.Type): Unit = {
    put_status_in(status_in)
  }


  /** helper function to check Status_Reporting_Thread_control_process_status_reporting's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param status_out method that will be called with the value of the outgoing data
   *        port 'status_out'.
   */
  def check_concrete_output(status_out: FAA_Autopilot_Engagement.AP_Status.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val status_outValue: FAA_Autopilot_Engagement.AP_Status.Type = get_status_out().get
    if(!status_out(status_outValue)) {
      testFailures = testFailures :+ st"'status_out' did not match expected: value of the outgoing data port is ${status_outValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_status_in(value : FAA_Autopilot_Engagement.AP_Status.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting.operational_api.status_in_Id, FAA_Autopilot_Engagement.AP_Status_Payload(value))
  }

  // getter for out DataPort
  def get_status_out(): Option[FAA_Autopilot_Engagement.AP_Status.Type] = {
    val value: Option[FAA_Autopilot_Engagement.AP_Status.Type] = get_status_out_payload() match {
      case Some(FAA_Autopilot_Engagement.AP_Status_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port status_out.  Expecting 'FAA_Autopilot_Engagement.AP_Status_Payload' but received ${v}")
      case _ => None[FAA_Autopilot_Engagement.AP_Status.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_status_out_payload(): Option[FAA_Autopilot_Engagement.AP_Status_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting.initialization_api.status_out_Id).asInstanceOf[Option[FAA_Autopilot_Engagement.AP_Status_Payload]]
  }

}
